function renderStats(){const n=document.getElementById("stats-grid");n&&"undefined"!=typeof NARASIMHAVARMAN_INFO&&(n.innerHTML=NARASIMHAVARMAN_INFO.quickStats.map(n=>`\n        <div class="stat-card">\n            <span class="stat-icon">${n.icon}</span>\n            <div class="stat-val">${n.value}</div>\n            <div class="stat-lbl">${n.label}</div>\n        </div>\n    `).join(""))}function renderMonuments(){const n=document.getElementById("monuments-grid");n&&"undefined"!=typeof MAMALLAPURAM_MONUMENTS&&(n.innerHTML=MAMALLAPURAM_MONUMENTS.map(n=>`\n        <div class="monument-card">\n            <span class="style-tag">${n.style}</span>\n            <h3>🛕 ${n.title}</h3>\n            <p>${n.description}</p>\n            <p class="sig-text"><strong>Architectural Impact:</strong> ${n.significance}</p>\n        </div>\n    `).join(""))}function renderVatapiCampaign(){const n=document.getElementById("vatapi-grid");n&&"undefined"!=typeof VATAPI_CAMPAIGN&&(n.innerHTML=VATAPI_CAMPAIGN.map(n=>`\n        <div class="vatapi-card">\n            <h3>⚔️ ${n.stage}</h3>\n            <p>${n.detail}</p>\n        </div>\n    `).join(""))}function renderForeignRelations(){const n=document.getElementById("foreign-grid");n&&"undefined"!=typeof FOREIGN_RELATIONS&&(n.innerHTML=FOREIGN_RELATIONS.map(n=>`\n        <div class="foreign-card">\n            <h3>🌏 ${n.title}</h3>\n            <p>${n.record}</p>\n        </div>\n    `).join(""))}function renderTimeline(){const n=document.getElementById("timeline-container");n&&"undefined"!=typeof TIMELINE_EVENTS&&(n.innerHTML=TIMELINE_EVENTS.map(n=>`\n        <div class="timeline-card">\n            <div class="timeline-year">${n.year}</div>\n            <div class="timeline-content">\n                <h3>${n.title}</h3>\n                <p>${n.description}</p>\n            </div>\n        </div>\n    `).join(""))}function renderReferences(){const n=document.getElementById("references-list");n&&"undefined"!=typeof REFERENCES&&(n.innerHTML=REFERENCES.map(n=>`\n        <li>\n            <a href="${n.link}" target="_blank" rel="noopener noreferrer">📚 ${n.text}</a>\n        </li>\n    `).join(""))}function initThemeToggle(){const n=document.getElementById("theme-toggle");n&&n.addEventListener("click",()=>{const e=document.body.classList.toggle("light-theme");localStorage.setItem("theme",e?"light":"dark"),n.textContent=e?"🌙":"☀️"})}document.addEventListener("DOMContentLoaded",()=>{renderStats(),renderMonuments(),renderVatapiCampaign(),renderForeignRelations(),renderTimeline(),renderReferences(),initThemeToggle()});